from typing import Any


class EnvCfgError(Exception):
    """Raised when an environment variable is invalid.

    Attributes:
        key: The configuration key (e.g. "server.port").
        expected: The type name expected (e.g. "int").
        got: The actual value or "unbound".
    """

    def __init__(self, key: str, expected: str, got: str):
        super().__init__(f"{key}: expected {expected}, got {got}")
        self.key = key
        self.expected = expected
        self.got = got


def _coerce(value: str, expected_type: type) -> Any:
    """Coerce a string to the expected type.

    Raises EnvCfgError if coercion fails.
    """
    if expected_type is int:
        try:
            return int(value)
        except ValueError:
            raise EnvCfgError(value, "int", value)
    if expected_type is float:
        try:
            return float(value)
        except ValueError:
            raise EnvCfgError(value, "float", value)
    if expected_type is bool:
        lower = value.lower()
        if lower in ("true", "1", "yes"):
            return True
        if lower in ("false", "0", "no"):
            return False
        raise EnvCfgError(value, "bool", value)
    if expected_type is str:
        return value
    raise EnvCfgError(value, str(expected_type), value)


def _parse_env_key(env_prefix: str, key: str) -> str:
    """Convert a nested key like "server.port" into an env var name.

    The prefix is prepended and all parts are joined with "__" and uppercased.
    """
    parts = [env_prefix] + key.split(".")
    return "__".join(p.upper() for p in parts)


