import os
import tempfile
import pytest
from envcfg import EnvCfgError, load_config


def _make_defaults():
    return {
        "server": {"port": 8080, "host": "localhost"},
        "debug": False,
        "app": {"name": "myapp"},
    }


def _make_env(prefix="APP"):
    return {f"{prefix}__{k}": v for k, v in os.environ.items() if k.startswith(f"{prefix}__")}


class TestPrecedence:
    def test_defaults_only(self):
        cfg = load_config(_make_defaults())
        assert cfg["server"]["port"] == 8080
        assert cfg["debug"] is False

    def test_toml_over_defaults(self):
        with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
            f.write(b'[server]\nport = 9000\n')
            toml_path = f.name
        try:
            cfg = load_config(_make_defaults(), toml_path=toml_path)
            assert cfg["server"]["port"] == 9000
            assert cfg["server"]["host"] == "localhost"  # defaults preserved
        finally:
            os.unlink(toml_path)

    def test_env_over_toml(self):
        with tempfile.NamedTemporaryFile(suffix=".toml", delete=False) as f:
            f.write(b'[server]\nport = 9000\n')
            toml_path = f.name
        try:
            cfg = load_config(_make_defaults(), toml_path=toml_path,
                              env={"APP__SERVER__PORT": "9090"})
            assert cfg["server"]["port"] == 9090
        finally:
            os.unlink(toml_path)

    def test_env_over_defaults(self):
        cfg = load_config(_make_defaults(),
                          env={"APP__DEBUG": "true"})
        assert cfg["debug"] is True


